bool BrowserHost_GetAllRegions_ForwardToCallback::Accept(
    mojo::Message* message) {
  DCHECK(message->is_serialized());
  internal::BrowserHost_GetAllRegions_ResponseParams_Data* params =
      reinterpret_cast<
          internal::BrowserHost_GetAllRegions_ResponseParams_Data*>(
              message->mutable_payload());
  

  // Validation for BrowserHost.3
  bool success = true;
  std::vector<VpnRegionPtr> p_regions{};
  BrowserHost_GetAllRegions_ResponseParamsDataView input_data_view(params, message);
  
  if (success && !input_data_view.ReadRegions(&p_regions))
    success = false;
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        BrowserHost::Name_, 3, true);
    return false;
  }
  if (!callback_.is_null()) {
    std::move(callback_).Run(
std::move(p_regions));
  }
  return true;
}

void BrowserHost_GetAllRegions_ProxyToResponder::Run(
    std::vector<VpnRegionPtr> in_regions) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send reply brave_vpn::mojom::BrowserHost::GetAllRegions", "async_response_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("regions"), in_regions,
                        "<value of type std::vector<VpnRegionPtr>>");
   });
#endif

  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::BrowserHost::kGetAllRegions), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::brave_vpn::mojom::internal::BrowserHost_GetAllRegions_ResponseParams_Data> params(
          message);
  params.Allocate();
  mojo::internal::MessageFragment<
      typename decltype(params->regions)::BaseType>
      regions_fragment(params.message());
  constexpr const mojo::internal::ContainerValidateParams& regions_validate_params =
      mojo::internal::GetArrayValidator<0, false, nullptr>();
  
  mojo::internal::Serialize<mojo::ArrayDataView<::brave_vpn::mojom::VpnRegionDataView>>(
    in_regions,
    regions_fragment,
    &regions_validate_params);

  params->regions.Set(
      regions_fragment.is_null() ? nullptr : regions_fragment.data());

  
  MOJO_INTERNAL_CHECK_SERIALIZATION(
    mojo::internal::SendValidation::kDefault,
    !(params->regions.is_null()),
    mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
    "null regions in ");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(BrowserHost::Name_);
  message.set_method_name("GetAllRegions");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

