bool StructTraits<::brave_vpn::mojom::VpnRegion::DataView, ::brave_vpn::mojom::VpnRegionPtr>::Read(
    ::brave_vpn::mojom::VpnRegion::DataView input,
    ::brave_vpn::mojom::VpnRegionPtr* output) {
  bool success = true;
  ::brave_vpn::mojom::VpnRegionPtr result(::brave_vpn::mojom::VpnRegion::New());
  
      if (success && !input.ReadName(&result->name))
        success = false;
  *output = std::move(result);
  return success;
}

